            setTimeout(() => { charge = 99; }, 2000);
        } else {
            charge += Math.random() * 0.5;
            corePercent.style.color = 'var(--cyan)';
            corePercent.textContent = Math.floor(charge) + '%';
        }
    }
    setInterval(jitterCore, 500);

