    --border-glow: 0 0 10px rgba(0, 242, 255, 0.5);
}

body, html {
    margin: 0;
    padding: 0;
    width: 100%;
    height: 100%;
    background-color: var(--bg-dark);
    background-image: 
        linear-gradient(rgba(0, 242, 255, 0.05) 1px, transparent 1px),
        linear-gradient(90deg, rgba(0, 242, 255, 0.05) 1px, transparent 1px);
    background-size: 50px 50px;
    color: var(--cyan);
    font-family: 'Courier New', Courier, monospace;
    overflow: hidden;
    user-select: none;
}

/* Boot Screen */
#boot-screen {
    position: fixed;
    top: 0;
    left: 0;
    width: 100%;
    height: 100%;
    background: black;
    z-index: 1000;
    display: flex;
    justify-content: center;
    align-items: center;
    transition: opacity 1s ease-out;
}

#boot-screen.fade-out {
    opacity: 0;
    pointer-events: none;
}

.boot-text {
    width: 400px;
    font-size: 14px;
}

.loading-bar {
    width: 100%;
    height: 4px;
    background: #111;
    margin-top: 20px;
    border: 1px solid var(--cyan);
}

.progress {
    width: 0%;
    height: 100%;
    background: var(--cyan);
    box-shadow: var(--border-glow);
    animation: load 3s forwards ease-in-out;
}

@keyframes load {
    0% { width: 0%; }
    20% { width: 15%; }
    50% { width: 60%; }
    100% { width: 100%; }
}

/* Main Container */
#cockpit-container {
    position: relative;
    width: 100vw;
    height: 100vh;
    display: flex;
    justify-content: space-between;
    padding: 40px;
    box-sizing: border-box;
    perspective: 1000px;
}

/* Overlays */
.overlay {
    position: absolute;
    top: 0;
    left: 0;
    width: 100%;
    height: 100%;
    pointer-events: none;
    z-index: 10;
}

.crt {
    background: linear-gradient(rgba(18, 16, 16, 0) 50%, rgba(0, 0, 0, 0.25) 50%), 
                linear-gradient(90deg, rgba(255, 0, 0, 0.06), rgba(0, 255, 0, 0.02), rgba(0, 0, 255, 0.06));
    background-size: 100% 4px, 3px 100%;
}

.vignette {
    background: radial-gradient(circle, transparent 40%, rgba(0,0,0,0.8) 100%);
}

/* HUD Panels */
.hud-panel {
    background: var(--panel-bg);
    border: 1px solid var(--cyan);
    padding: 20px;
    backdrop-filter: blur(5px);
    box-shadow: var(--border-glow);
    display: flex;
    flex-direction: column;
    gap: 15px;
    transition: transform 0.1s ease-out;
}

.left { width: 300px; align-self: flex-start; border-left: 5px solid var(--cyan); }
.right { width: 300px; align-self: flex-end; border-right: 5px solid var(--cyan); text-align: right; }
.center { 
    background: none; 
    border: none; 
    box-shadow: none; 
    flex-grow: 1; 
    justify-content: center; 
    align-items: center; 
    backdrop-filter: none;
}

/* Bars */
.stat-row .label { font-size: 12px; margin-bottom: 5px; display: block; }
.bar-container { width: 100%; height: 10px; background: rgba(0,0,0,0.5); border: 1px solid var(--cyan); }
.bar { height: 100%; transition: width 0.5s ease; }
.hull { background: var(--orange); }
.shield { background: var(--cyan); }

/* Crosshair */
.crosshair {
    position: relative;
    width: 100px;
    height: 100px;
}

.bracket {
    position: absolute;
    width: 20px;
    height: 20px;
    border: 2px solid var(--cyan);
}

.top-left { top: 0; left: 0; border-right: 0; border-bottom: 0; }
.top-right { top: 0; right: 0; border-left: 0; border-bottom: 0; }
.bottom-left { bottom: 0; left: 0; border-right: 0; border-top: 0; }
.bottom-right { bottom: 0; right: 0; border-left: 0; border-top: 0; }
.center-dot {
    position: absolute;
    top: 50%;
    left: 50%;
    width: 4px;
    height: 4px;
    background: var(--orange);
    transform: translate(-50%, -50%);
    border-radius: 50%;
}

/* Core Meter */
.core-meter {
    margin-top: 50px;
    text-align: center;
}

.core-label { font-size: 12px; color: var(--orange); letter-spacing: 2px; }
.core-percent { font-size: 32px; font-weight: bold; margin-bottom: 10px; }
.core-ring {
    width: 60px;
    height: 60px;
    border: 4px solid var(--orange);
    border-top-color: transparent;
    border-radius: 50%;
    margin: 0 auto;
    animation: spin 2s linear infinite;
}

@keyframes spin { 100% { transform: rotate(360deg); } }

/* Clock & Comms */
#clock { font-size: 40px; font-weight: bold; }
.comms-log { font-size: 11px; color: rgba(0, 242, 255, 0.7); max-width: 250px; }

/* Compass */
.compass {
    display: flex;
    justify-content: space-around;
    border-top: 1px solid var(--cyan);
    padding-top: 10px;
    margin-top: 20px;
}

